const body = $json.body || {};
const application_id = body.application_id || 'UNKNOWN';
const timeline = [
  { status: 'submitted', label: 'Application submitted', at: '2026-09-20T09:00:00Z' },
  { status: 'under_review', label: 'Under review by department', at: '2026-09-21T11:30:00Z' },
  { status: 'approved', label: 'Approved', at: '2026-09-23T10:15:00Z' },
];
return {
  json: {
    application_id,
    current_status: timeline[timeline.length - 1].status,
    timeline,
    mocked: true,
    note: body.application_id
      ? 'This is a mocked status sequence, not live portal polling.'
      : 'No application_id was provided; returning the mocked status sequence anyway.',
  },
};
